const esc=(s:unknown)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
type Selection={kind:'object'|'region';id:string}|null;
let project:EditorProject,selected:Selection=null,activeLayer='',chosenAsset='',tool='select',ready=false,playing=false,player:Motion={x:0,y:0,direction:'south',moving:false};
