let lastMinimap=0;
let replacingPart:{assetId:string;partId:string}|null=null;
let view={x:0,y:0,zoom:1},draft:Array<{x:number;y:number}>=[],hover={x:0,y:0},space=false,last=performance.now();
let drag:{mode:'pan'|'selection'|'marquee'|'brush'|'erase'|'vertex'|'rect';start:{x:number;y:number};screen:{x:number;y:number};before:EditorProject;index?:number;origin?:any;additive?:boolean;seen?:Set<string>;lastPoint?:{x:number;y:number}}|null=null;
