const level=():EditorLevel=>project.levels.find(l=>l.id===project.activeLevelId)!;
const layerName=(id:string)=>level().layers.find(l=>l.id===id)?.name??'';
const object=()=>selected?.kind==='object'?level().objects.find(o=>o.id===selected!.id):undefined;
const region=()=>selected?.kind==='region'?level().regions.find(r=>r.id===selected!.id):undefined;
function setSelection(items:EntitySelection[]):void {selections=[...new Map(items.filter(s=>entity(level(),s)).map(s=>[entityKey(s),s])).values()];selected=selections.at(-1)??null;}
function clearSelection():void {selections=[];selected=null;}
function choose(s:Selection,additive=false,individual=false):void {if(!s){if(!additive)clearSelection();return;}const members=individual?[s]:groupMembers(level(),s),keys=new Set(members.map(entityKey));setSelection(additive?(members.every(m=>selections.some(v=>entityKey(v)===entityKey(m)))?selections.filter(v=>!keys.has(entityKey(v))):[...selections,...members.filter(v=>entityKey(v)!==entityKey(s)),s]):[...members.filter(v=>entityKey(v)!==entityKey(s)),s]);}
const objectLayerLocked=(o:EditorObject)=>Boolean(level().layers.find(l=>l.id===o.layerId)?.locked||(project.assets.find(a=>a.id===o.assetId)?.parts.some(p=>p.cover)&&level().layers.find(l=>l.id===o.coverLayerId)?.locked));
const status=(s:string)=>{el('status').textContent=s;};
const snap=(n:number)=>Math.round(n/Number(el<HTMLSelectElement>('snap').value))*Number(el<HTMLSelectElement>('snap').value);
const world=(e:{clientX:number;clientY:number})=>{const b=canvas.getBoundingClientRect();return {x:(e.clientX-b.left-view.x)/view.zoom,y:(e.clientY-b.top-view.y)/view.zoom};};
const snapped=(p:{x:number;y:number})=>({x:snap(p.x),y:snap(p.y)});
const image=async(file:string)=>{if(images.has(file))return;const img=new Image();img.src=file;await img.decode();images.set(file,{image:img,mask:imageAlpha(img)});};
async function loadAssets(p=project):Promise<void>{for(const a of p.assets)for(const part of a.parts){if(part.file.startsWith('/assets/map-kit/')&&!libraryFiles.has(part.file))throw new Error(`Asset cũ đã xóa khỏi thư viện: ${a.name}. Bản lưu vẫn được giữ; cần PNG mới để mở lại.`);}await Promise.all(p.assets.flatMap(a=>a.parts.map(p=>image(p.file))));for(const a of p.assets){for(const part of a.parts){const i=images.get(part.file)!.image;if(i.width!==a.width||i.height!==a.height)throw new Error(`Cỡ PNG không khớp: ${a.name}`);}if(a.parts.length>1){const c=document.createElement('canvas');c.width=a.width;c.height=a.height;for(const part of a.parts)c.getContext('2d')!.drawImage(images.get(part.file)!.image,0,0);thumbnails.set(a.id,c.toDataURL());}}}
function localSave():void {
  try{localStorage.setItem(`game-solo-map-editor:${project.id}`,JSON.stringify(project));localStorage.setItem('game-solo-map-editor-last',project.id);}
  catch{status('Bản nháp vượt bộ nhớ trình duyệt. Bấm Lưu dự án hoặc Xuất JSON để giữ dữ liệu.');}
}
function changed(before:EditorProject):void {
  try{project=parseProject(project);}catch(error){project=before;status(String(error));ui();return;}
  el('issues').innerHTML='<p class="hint">Dữ liệu đã đổi. Bấm Kiểm tra để cập nhật kết quả.</p>';undo.push(before);if(undo.length>40)undo.shift();redo.length=0;
  clearTimeout(savedTimer);savedTimer=setTimeout(localSave,350);ui();status('Bản nháp đã sửa · Ctrl+S để lưu vào dự án.');
}
function edit(fn:()=>void):void {if(playing){status('Dừng Test để chỉnh map.');return;}const before=structuredClone(project);try{fn();changed(before);}catch(error){project=before;clearSelection();ui();status(String(error));}}
function fit():void {const l=level();view.zoom=Math.min(1,(viewport.clientWidth-60)/l.width,(viewport.clientHeight-60)/l.height);view.zoom=Math.max(.25,view.zoom);view.x=(viewport.clientWidth-l.width*view.zoom)/2;view.y=(viewport.clientHeight-l.height*view.zoom)/2;el<HTMLInputElement>('zoom').value=String(Math.round(view.zoom*100)/100);}
function zoomTo(z:number,p={x:viewport.clientWidth/2,y:viewport.clientHeight/2}):void {const wx=(p.x-view.x)/view.zoom,wy=(p.y-view.y)/view.zoom;view.zoom=Math.max(.25,Math.min(4,z));view.x=p.x-wx*view.zoom;view.y=p.y-wy*view.zoom;el<HTMLInputElement>('zoom').value=String(Math.round(view.zoom*100)/100);}
function setTool(value:string):void {if(playing)return;tool=value;draft=[];document.querySelectorAll<HTMLButtonElement>('[data-tool]').forEach(b=>b.classList.toggle('active',b.dataset.tool===tool));status(tool==='place'?'Bấm vào map để đặt asset; Esc trở lại chọn.':tool.endsWith('poly')?'Bấm các đỉnh, Enter để hoàn tất; Esc hủy.':'Kéo để chỉnh; Space hoặc chuột giữa để di chuyển khung.');}
function activate(id:string):void {project.activeLevelId=id;clearSelection();activeLayer=level().layers.find(l=>l.kind==='depth')?.id??level().layers[0].id;draft=[];keys.clear();if(playing){player={...level().spawn,direction:'south',moving:false};}fit();ui();localSave();}
function download(name:string,value:unknown):void {const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
async function savedList():Promise<void>{
  const select=el<HTMLSelectElement>('saved-projects');select.replaceChildren(new Option('Mở bản lưu…',''));
  try{const r=await fetch('/api/map-editor/projects');if(r.ok){for(const p of (await r.json()).projects)select.add(new Option(`${p.name} · dự án`,p.id));}}catch{/* Browser drafts still work without the local API. */}
  for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i)!;if(!key.startsWith('game-solo-map-editor:'))continue;try{const p=parseProject(JSON.parse(localStorage.getItem(key)!));select.add(new Option(`${p.name} · nháp trình duyệt`,`draft:${p.id}`));}catch{/* Preserve invalid old drafts. */}}
}
function save():Promise<void>{localSave();const snapshot=structuredClone(project);status('Đang chờ lưu vào dự án…');const work=async()=>{try{const r=await fetch(`/api/map-editor/projects/${snapshot.id}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(snapshot)});const result=await r.json();if(!r.ok)throw new Error(result.error);if(project.id===snapshot.id)status(JSON.stringify(project)===JSON.stringify(snapshot)?`Đã lưu: ${result.path}`:'Đã lưu phiên bản vừa gửi; còn thay đổi mới chưa lưu.');await savedList();}catch(error){status(`Chưa lưu được file dự án: ${String(error)}. Xuất JSON để lưu bản này.`);}};saveQueue=saveQueue.then(work,work);return saveQueue;}
function palette():void {
  const search=el<HTMLInputElement>('search').value.toLocaleLowerCase('vi'),category=el<HTMLSelectElement>('asset-category').value;
  el('palette').innerHTML=project.assets.filter(a=>a.name.toLocaleLowerCase('vi').includes(search)&&(!category||(a.category??'other')===category)).map(a=>`<button class="asset-card ${a.id===chosenAsset?'selected':''}" draggable="true" data-asset="${esc(a.id)}" title="${a.width} × ${a.height}"><img draggable="false" loading="lazy" src="${esc(thumbnails.get(a.id)??a.parts[0].file)}" alt="" /><span>${esc(a.name)}</span></button>`).join('')||`<p class="hint">${project.assets.length?'Không có asset khớp từ khóa.':'Thư viện trống. Nhập PNG riêng để bắt đầu bộ map mới.'}</p>`;
}
const inputField=(name:string,label:string,value:unknown,type='text',extra='')=>`<label class="form-row">${label}<input data-field="${name}" type="${type}" value="${esc(value)}" ${extra} /></label>`;
const selectField=(name:string,label:string,value:string,options:Array<[string,string]>)=>`<label class="form-row">${label}<select data-field="${name}">${options.map(([id,text])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(text)}</option>`).join('')}</select></label>`;
function inspector():void {
  const o=object(),r=region(),l=level();let html='';
  if(selections.length>1){const b=selectionBounds(project,l,selections);html=`<p>${selections.length} đối tượng / vùng đang chọn.</p>`+inputField('selectionX','X · mép trái',b.left,'number')+inputField('selectionY','Y · mép trên',b.top,'number')+'<p class="hint">Kéo cả cụm hoặc dùng căn chỉnh/nhóm trên thanh công cụ. Alt+bấm để chọn riêng một thành phần.</p>';}else if(o){html=inputField('name','Tên đối tượng',o.name)+`<div class="form-pair">${inputField('x','X · điểm chân',o.x,'number')}${inputField('y','Y · điểm chân',o.y,'number')}</div>`+inputField('scale','Tỷ lệ',o.scale,'number','min=".1" max="4" step=".1"')+inputField('opacity','Độ hiện',o.opacity,'number','min="0" max="1" step=".05"')+selectField('layerId','Layer thân/vật',o.layerId,l.layers.filter(l=>l.kind!=='regions').map(l=>[l.id,l.name]))+selectField('coverLayerId','Layer tán/mái',o.coverLayerId,l.layers.filter(l=>l.kind==='cover').map(l=>[l.id,l.name]))+selectField('flipX','Lật ngang',String(o.flipX),[['false','Không'],['true','Có']])+selectField('locked','Khóa đối tượng',String(o.locked),[['false','Không'],['true','Có']]);}
  else if(r){html=inputField('name','Tên vùng',r.name)+selectField('kind','Loại vùng',r.kind,[['walk','Vùng đi'],['block','Vùng chặn'],['portal','Cửa nối level']])+selectField('layerId','Layer dữ liệu',r.layerId,l.layers.filter(l=>l.kind==='regions').map(l=>[l.id,l.name]))+selectField('enabled','Hoạt động',String(r.enabled),[['true','Có'],['false','Không']])+`<label class="form-row">Các đỉnh · x,y mỗi dòng<textarea data-field="points">${r.points.map(p=>`${p.x},${p.y}`).join('\n')}</textarea></label><p class="hint">Kéo điểm để sửa. Shift+bấm cạnh để thêm đỉnh; Alt+bấm điểm để xóa.</p>`;
    if(r.kind==='portal')html+=selectField('targetLevelId','Level đích',r.targetLevelId,[['','Chưa chọn'],...project.levels.map(l=>[l.id,l.name] as [string,string])])+inputField('targetX','X đến · để trống dùng spawn',r.target?.x??'','number')+inputField('targetY','Y đến',r.target?.y??'','number');
  }else {html=inputField('levelName','Tên level',l.name)+`<div class="form-pair">${inputField('width','Rộng',l.width,'number','min="64" max="8192"')}${inputField('height','Cao',l.height,'number','min="64" max="8192"')}</div>`+inputField('background','Màu nền',l.background,'color')+selectField('walkPolicy','Luật đi',l.walkPolicy,[['full','Đi trong toàn level, trừ vùng chặn'],['regions','Chỉ đi trong vùng đi đã vẽ']])+`<div class="form-pair">${inputField('spawnX','Spawn X',l.spawn.x,'number')}${inputField('spawnY','Spawn Y',l.spawn.y,'number')}</div>`;
    const layer=l.layers.find(x=>x.id===activeLayer);if(layer)html+='<h2>Layer đang chọn</h2>'+inputField('layerName','Tên layer',layer.name)+selectField('layerKind','Cách hiển thị',layer.kind,[['ground','Nền'],['decor','Trang trí thấp'],['depth','Theo chân'],['cover','Tán/mái · theo chân'],['regions','Dữ liệu vùng']]);
  }
  if(o&&selections.length===1){const a=project.assets.find(a=>a.id===o.assetId)!,p=o.pivot??a.pivot;html+=`<div class="form-pair">${inputField('pivotX','Pivot X · trong PNG',p.x,'number')}${inputField('pivotY','Pivot Y · trong PNG',p.y,'number')}</div><p class="hint">Pivot là điểm đặt và điểm chân để xếp lớp. Các part cùng nhóm dùng chung pivot.</p>`;}
  el('inspector').innerHTML=html;el('inspector').querySelectorAll<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>('[data-field]').forEach(n=>n.disabled=playing);
  const locked=selections.some(s=>{const item=entity(l,s);return s.kind==='object'?Boolean(item&&((item as EditorObject).locked||objectLayerLocked(item as EditorObject))):Boolean(l.layers.find(x=>x.id===item?.layerId)?.locked);});
  if(locked)el('inspector').querySelectorAll<HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement>('[data-field]').forEach(n=>{if(n.dataset.field!=='locked'||o&&objectLayerLocked(o))n.disabled=true;});
}
function ui():void {
  if(!project)return;setSelection(selections);const l=level();el<HTMLInputElement>('project-name').value=project.name;
  el<HTMLSelectElement>('level').replaceChildren(...project.levels.map(x=>new Option(x.name,x.id)));el<HTMLSelectElement>('level').value=l.id;
  el('layers').innerHTML=[...l.layers].reverse().map(x=>`<div class="layer-row ${x.id===activeLayer?'selected':''}" data-layer="${x.id}"><button data-layer-select="${x.id}">${esc(x.name)}</button>${(['visible','locked','enabled'] as const).map((key,i)=>`<label title="${['Hiện trong editor','Khóa sửa','Hoạt động trong Test/xuất'][i]}"><input type="checkbox" data-layer-flag="${key}" data-id="${x.id}" ${x[key]?'checked':''} />${['👁','🔒','✓'][i]}</label>`).join('')}</div>`).join('');
  el('entities').innerHTML=[...l.objects.map(o=>({id:o.id,kind:'object',name:o.name})),...l.regions.map(r=>({id:r.id,kind:'region',name:`${r.kind==='block'?'⛔':r.kind==='portal'?'↗':'◇'} ${r.name}`}))].map(x=>`<button class="entity ${selections.some(s=>s.id===x.id)?'selected':''}" data-entity="${x.id}" data-kind="${x.kind}">${esc(x.name)}</button>`).join('')||'<p class="hint">Level trống. Kéo asset vào khung để bắt đầu.</p>';
  el('flows').innerHTML=project.levels.flatMap(a=>a.regions.filter(r=>r.kind==='portal').map(r=>{const dest=project.levels.find(l=>l.id===r.targetLevelId);return `<div class="flow ${dest?'':'warning'}">${esc(a.name)} → ${esc(dest?.name??'chưa chọn đích')}<br />${esc(r.name)} · ${r.enabled?'hoạt động':'tắt'}</div>`;})).join('')||'<p class="hint">Chưa có cửa nối level.</p>';
  el<HTMLButtonElement>('undo').disabled=!undo.length||playing;el<HTMLButtonElement>('redo').disabled=!redo.length||playing;
  el('play').textContent=playing?'■ Dừng Test':'▶ Test map';document.body.classList.toggle('testing',playing);el('mode-label').textContent=playing?'TEST · WASD / mũi tên · E qua cửa':`BIÊN TẬP · ${l.name}`;
  el('layers').querySelectorAll<HTMLInputElement>('input').forEach(n=>n.disabled=playing);
  for(const id of ['project-name','new-project','add-level','clone-level','delete-level','duplicate','remove','add-layer','layer-up','layer-down','delete-layer','import-asset','import-project','import-level'])el<HTMLInputElement|HTMLButtonElement>(id).disabled=playing;
  el('counts').textContent=`${l.width} × ${l.height} · ${l.objects.length} vật · ${l.regions.length} vùng · ${selections.length} chọn`;palette();inspector();engineUi();
}
function stamp(assetId:string,p:{x:number;y:number}):EditorObject|null {
  const a=project.assets.find(x=>x.id===assetId);if(!a||level().objects.length>=10000)return null;
  const current=level().layers.find(l=>l.id===activeLayer&&l.kind!=='regions'),base=current??level().layers.find(l=>l.kind===(a.defaultLayer??'depth')),cover=level().layers.find(l=>l.kind==='cover');
  if(!base||!cover||base.locked||(a.parts.some(p=>p.cover)&&cover.locked)){status('Cần layer đặt và Tán/Mái đã mở khóa.');return null;}
  const o:EditorObject={id:uid(),name:a.name,assetId:a.id,layerId:base.id,coverLayerId:cover.id,...p,scale:1,flipX:false,opacity:1,locked:false};level().objects.push(o);activeLayer=base.id;return o;
}
function place(assetId:string,p:{x:number;y:number}):void {if(playing)return;edit(()=>{const o=stamp(assetId,snapped(p));if(o)choose({kind:'object',id:o.id});});}
function addRegion(points:Array<{x:number;y:number}>):void {
  const l=level(),layer=l.layers.find(l=>l.id===activeLayer&&l.kind==='regions')??l.layers.find(l=>l.kind==='regions');if(!layer||layer.locked){status('Cần layer Vùng hoạt động đã mở khóa.');return;}
  const kind=tool.startsWith('walk')?'walk':tool.startsWith('portal')?'portal':'block';
  edit(()=>{const r:EditorRegion={id:uid(),name:kind==='walk'?'Vùng đi':kind==='block'?'Vùng chặn':'Cửa nối',kind,layerId:layer.id,points,enabled:true,targetLevelId:'',target:null};l.regions.push(r);choose({kind:'region',id:r.id});activeLayer=layer.id;});
}
const bounds=objectBounds;
function selectionCandidates():EntitySelection[] {const l=level(),solo=el<HTMLInputElement>('solo-layer').checked,visible=(id:string)=>l.layers.some(v=>v.id===id&&v.visible&&(!solo||id===activeLayer));
  const items:EntitySelection[]=[...l.objects.filter(o=>{const a=project.assets.find(a=>a.id===o.assetId);return !o.locked&&!objectLayerLocked(o)&&a?.parts.some(p=>visible(p.cover?o.coverLayerId:o.layerId));}).map(o=>({kind:'object' as const,id:o.id})),...l.regions.filter(r=>el<HTMLInputElement>('show-regions').checked&&visible(r.layerId)&&!l.layers.find(v=>v.id===r.layerId)?.locked).map(r=>({kind:'region' as const,id:r.id}))];
  return items.filter(s=>groupMembers(l,s).every(m=>{const item=entity(l,m)!;return m.kind==='object'?!((item as EditorObject).locked||objectLayerLocked(item as EditorObject)):!l.layers.find(v=>v.id===item.layerId)?.locked;}));
}
function hit(p:{x:number;y:number}):Selection {
  const l=level();if(el<HTMLInputElement>('show-regions').checked)for(const r of [...l.regions].reverse()){const layer=l.layers.find(x=>x.id===r.layerId);if(layer?.visible&&!layer.locked&&(!el<HTMLInputElement>('solo-layer').checked||layer.id===activeLayer)&&inside(p,r.points))return {kind:'region',id:r.id};}
  if(p.x<0||p.y<0||p.x>l.width||p.y>l.height)return null;
  const rows=l.objects.flatMap((o,index)=>{if(objectLayerLocked(o)||o.locked)return [];const a=project.assets.find(a=>a.id===o.assetId)!;return a.parts.flatMap(part=>{const layer=l.layers.find(x=>x.id===(part.cover?o.coverLayerId:o.layerId));if(!layer?.visible||(el<HTMLInputElement>('solo-layer').checked&&layer.id!==activeLayer))return [];return [{o,a,part,index,band:layer.kind==='ground'?0:layer.kind==='decor'?1:2,order:l.layers.indexOf(layer),cover:part.cover||layer.kind==='cover'}];});});
  rows.sort((a,b)=>a.band-b.band||(a.band===2?a.o.y-b.o.y||Number(a.cover)-Number(b.cover):a.order-b.order)||a.index-b.index).reverse();
  for(const {o,a,part} of rows){const b=bounds(o,a);let x=Math.floor((p.x-b.left)/o.scale);const y=Math.floor((p.y-b.top)/o.scale);if(o.flipX)x=a.width-1-x;if(x<0||y<0||x>=a.width||y>=a.height)continue;if((images.get(part.file)?.mask.alpha[y*a.width+x]??0)>48)return {kind:'object',id:o.id};}
  return null;
}
canvas.addEventListener('dragover',e=>e.preventDefault());canvas.addEventListener('drop',e=>{e.preventDefault();place(e.dataTransfer?.getData('application/x-map-asset')??'',world(e));viewport.focus();});
el('palette').addEventListener('dragstart',e=>{const b=(e.target as HTMLElement).closest<HTMLElement>('[data-asset]');if(b){(e as DragEvent).dataTransfer?.setData('application/x-map-asset',b.dataset.asset!);}});
el('palette').addEventListener('click',e=>{const b=(e.target as HTMLElement).closest<HTMLElement>('[data-asset]');if(b){chosenAsset=b.dataset.asset!;chosenPrefab='';const a=project.assets.find(a=>a.id===chosenAsset)!;if(a.defaultLayer)activeLayer=level().layers.find(l=>l.kind===a.defaultLayer)?.id??activeLayer;setTool(['brush','paint-rect','erase'].includes(tool)?tool:'place');ui();}});
function brushStep():number {return Math.max(1,Math.min(2048,Number(el<HTMLInputElement>('brush-step').value)||32));}
function paintCell(p:{x:number;y:number}):void {const a=project.assets.find(a=>a.id===chosenAsset);if(!a)return;const base=level().layers.find(l=>l.id===activeLayer&&l.kind!=='regions')??level().layers.find(l=>l.kind===(a.defaultLayer??'depth')),cover=level().layers.find(l=>l.kind==='cover');if(!base||base.locked||!cover||(a.parts.some(p=>p.cover)&&cover.locked))return;
  const same=level().objects.filter(o=>o.layerId===base.id&&o.x===p.x&&o.y===p.y);if(same.some(o=>o.assetId===chosenAsset))return;
  if(a.category==='terrain'){const previous=same.filter(o=>project.assets.find(a=>a.id===o.assetId)?.category==='terrain');if(previous.some(o=>o.locked||objectLayerLocked(o)||o.groupId))return;const ids=new Set(previous.map(o=>o.id));level().objects=level().objects.filter(o=>!ids.has(o.id));}
  stamp(chosenAsset,p);
}
function brushPath(to:{x:number;y:number}):void {if(!drag||!['brush','erase'].includes(drag.mode))return;const step=brushStep();for(const p of gridStroke(drag.lastPoint??drag.start,to,step)){const key=`${p.x},${p.y}`;if(drag.seen!.has(key)||p.x<0||p.y<0||p.x>=level().width||p.y>=level().height)continue;drag.seen!.add(key);if(drag.mode==='erase'){level().objects=level().objects.filter(o=>o.layerId!==activeLayer||o.locked||objectLayerLocked(o)||o.groupId||Math.round(o.x/step)!==Math.round(p.x/step)||Math.round(o.y/step)!==Math.round(p.y/step));}else paintCell(p);}drag.lastPoint=to;}
canvas.addEventListener('pointerdown',e=>{
  if(!ready)return;viewport.focus();const p=world(e);hover=p;canvas.setPointerCapture(e.pointerId);
  if(e.button===1||space||tool==='pan'){e.preventDefault();drag={mode:'pan',start:p,screen:{x:e.clientX,y:e.clientY},before:structuredClone(project),origin:{...view}};return;}
  if(e.button!==0||playing)return;
  if(tool==='place'){place(chosenAsset,p);return;}
  if(tool==='prefab'){const f=project.prefabs?.find(f=>f.id===chosenPrefab);if(f)edit(()=>setSelection(instantiatePrefab(project,level(),f,snapped(p))));return;}
  if(tool==='brush'||tool==='erase'){if(tool==='brush'&&!chosenAsset){status('Chọn asset trước khi dùng cọ.');return;}if(level().layers.find(l=>l.id===activeLayer)?.locked){status('Layer đang khóa.');return;}clearSelection();drag={mode:tool,start:p,screen:{x:e.clientX,y:e.clientY},before:structuredClone(project),seen:new Set(),lastPoint:p};brushPath(p);return;}
  if(tool==='spawn'){edit(()=>level().spawn=snapped(p));return;}
  if(tool.endsWith('poly')){draft.push(snapped(p));return;}
  if(tool.endsWith('rect')){drag={mode:'rect',start:snapped(p),screen:{x:e.clientX,y:e.clientY},before:structuredClone(project)};return;}
  const r=region(),layer=r&&level().layers.find(l=>l.id===r.layerId),vertex=r&&selections.length===1&&!layer?.locked?r.points.findIndex(v=>Math.hypot(v.x-p.x,v.y-p.y)<10/view.zoom):-1;
  if(r&&vertex>=0&&e.altKey){if(r.points.length<=3){status('Đa giác cần ít nhất 3 đỉnh.');return;}edit(()=>r.points.splice(vertex,1));return;}
  if(r&&selections.length===1&&!layer?.locked&&e.shiftKey&&vertex<0){let edge=-1,best=10/view.zoom;for(let i=0;i<r.points.length;i++){const a=r.points[i],b=r.points[(i+1)%r.points.length],dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((p.x-a.x)*dx+(p.y-a.y)*dy)/(dx*dx+dy*dy||1))),distance=Math.hypot(p.x-a.x-dx*t,p.y-a.y-dy*t);if(distance<best){edge=i;best=distance;}}if(edge>=0){edit(()=>r.points.splice(edge+1,0,snapped(p)));return;}}
  if(r&&vertex>=0){drag={mode:'vertex',start:p,screen:{x:e.clientX,y:e.clientY},before:structuredClone(project),index:vertex};return;}
  const found=hit(p),additive=e.shiftKey||e.ctrlKey||e.metaKey;
  if(!found){if(!additive)clearSelection();drag={mode:'marquee',start:p,screen:{x:e.clientX,y:e.clientY},before:structuredClone(project),additive,origin:[...selections]};ui();return;}
  if(additive||!selections.some(s=>entityKey(s)===entityKey(found)))choose(found,additive,e.altKey);else if(e.altKey)choose(found,false,true);
  activeLayer=object()?.layerId??region()?.layerId??activeLayer;ui();if(!selections.length||!canEditSelection())return;
  drag={mode:'selection',start:p,screen:{x:e.clientX,y:e.clientY},before:structuredClone(project),origin:structuredClone(level())};
});
canvas.addEventListener('pointermove',e=>{const p=world(e);hover=p;el('coordinates').textContent=`${Math.round(p.x)}, ${Math.round(p.y)} · ${view.zoom.toFixed(2)}×`;if(!drag)return;
  if(drag.mode==='pan'){view.x=drag.origin.x+e.clientX-drag.screen.x;view.y=drag.origin.y+e.clientY-drag.screen.y;return;}
  if(drag.mode==='selection'){for(const s of selections){const source=entity(drag.origin,s)!,dest=entity(level(),s)!;if(s.kind==='object'){const o=dest as EditorObject,v=source as EditorObject;o.x=v.x;o.y=v.y;}else (dest as EditorRegion).points=structuredClone((source as EditorRegion).points);}translateEntities(level(),selections,snap(p.x-drag.start.x),snap(p.y-drag.start.y));}
  if(drag.mode==='vertex')region()!.points[drag.index!]=snapped(p);
  if(drag.mode==='brush'||drag.mode==='erase')brushPath(p);
});
canvas.addEventListener('pointerup',e=>{if(!drag)return;const d=drag,p=world(e);drag=null;
  if(d.mode==='marquee'){const left=Math.min(d.start.x,p.x),top=Math.min(d.start.y,p.y),right=Math.max(d.start.x,p.x),bottom=Math.max(d.start.y,p.y);if(right-left>3||bottom-top>3){const candidates=selectionCandidates();const found=candidates.filter(s=>{const b=entityBounds(project,level(),s);return b.left<right&&b.left+b.w>left&&b.top<bottom&&b.top+b.h>top;}).flatMap(s=>groupMembers(level(),s));setSelection([...(d.additive?d.origin:[]),...found]);}ui();return;}
  if(d.mode==='rect'){const a=d.start,b=snapped(p);if(tool==='paint-rect'){const step=brushStep(),left=Math.ceil(Math.min(a.x,b.x)/step)*step,top=Math.ceil(Math.min(a.y,b.y)/step)*step,right=Math.floor(Math.max(a.x,b.x)/step)*step,bottom=Math.floor(Math.max(a.y,b.y)/step)*step,count=(1+(right-left)/step)*(1+(bottom-top)/step);if(!chosenAsset){status('Chọn asset trước khi tô ô.');return;}if(count>2000){status('Mỗi lượt tô tối đa 2000 ô. Chia vùng nhỏ hơn.');return;}edit(()=>{for(let y=top;y<=bottom;y+=step)for(let x=left;x<=right;x+=step)if(x>=0&&y>=0&&x<level().width&&y<level().height)paintCell({x,y});});}
    else if(Math.abs(a.x-b.x)>=4&&Math.abs(a.y-b.y)>=4)addRegion([{x:a.x,y:a.y},{x:b.x,y:a.y},{x:b.x,y:b.y},{x:a.x,y:b.y}]);}
  else if(d.mode!=='pan'&&JSON.stringify(d.before.levels)!==JSON.stringify(project.levels))changed(d.before);ui();
});
canvas.addEventListener('pointercancel',()=>{if(drag&&drag.mode!=='pan'&&drag.mode!=='marquee')project=drag.before;drag=null;ui();});
canvas.addEventListener('wheel',e=>{e.preventDefault();const b=canvas.getBoundingClientRect();zoomTo(view.zoom*(e.deltaY<0?1.15:1/1.15),{x:e.clientX-b.left,y:e.clientY-b.top});},{passive:false});
const finish=()=>{if(draft.length>=3){addRegion([...draft]);draft=[];}else status('Cần ít nhất3 đỉnh.');};
el('finish-polygon').addEventListener('click',finish);document.querySelectorAll<HTMLElement>('[data-tool]').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool!)));
function canEditSelection():boolean {for(const s of selections){const item=entity(level(),s);if(s.kind==='object'&&item&&((item as EditorObject).locked||objectLayerLocked(item as EditorObject))||s.kind==='region'&&item&&level().layers.find(l=>l.id===item.layerId)?.locked){status('Có đối tượng hoặc layer đang khóa. Mở khóa trước khi sửa cả lựa chọn.');return false;}}return true;}
function remove():void {if(!selections.length||!canEditSelection())return;edit(()=>{const objects=new Set(selections.filter(s=>s.kind==='object').map(s=>s.id)),regions=new Set(selections.filter(s=>s.kind==='region').map(s=>s.id));level().objects=level().objects.filter(o=>!objects.has(o.id));level().regions=level().regions.filter(r=>!regions.has(r.id));clearSelection();});}
function duplicate():void {if(!selections.length||!canEditSelection())return;edit(()=>setSelection(duplicateEntities(level(),selections)));}
function history(back:boolean):void {if(playing)return;el('issues').innerHTML='<p class="hint">Bấm Kiểm tra để cập nhật sau undo/redo.</p>';const from=back?undo:redo,to=back?redo:undo,p=from.pop();if(p){to.push(structuredClone(project));project=p;clearSelection();if(!level().layers.some(l=>l.id===activeLayer))activeLayer=level().layers.find(l=>l.kind==='depth')?.id??level().layers[0].id;ui();localSave();void loadAssets();}}
function testMode():void {if(playing){playing=false;keys.clear();if(editView?.levelId===level().id){view={...editView.view};el<HTMLInputElement>('zoom').value=String(Math.round(view.zoom*100)/100);}else fit();el<HTMLInputElement>('show-regions').checked=true;ui();status('Trở lại biên tập.');return;}if(!editorWalkable(level(),level().spawn)){status('Spawn đang bị chặn hoặc chưa có vùng đi. Chỉnh Spawn / vẽ vùng đi trước khi Test.');return;}editView={levelId:level().id,view:{...view}};view.zoom=1;el<HTMLInputElement>('zoom').value='1';playing=true;clearSelection();draft=[];player={...level().spawn,direction:'south',moving:false};animation.set('stand','south');keys.clear();el<HTMLInputElement>('show-regions').checked=false;ui();viewport.focus();status('WASD / mũi tên để đi; E qua cửa nối; Esc dừng.');}
function traverse():void {const result=portalAt(project,level(),player);if(!result){status('Không ở trong cửa hợp lệ, hoặc level đích/vị trí đến chưa đi được.');return;}project.activeLevelId=result.level.id;player={...result.point,direction:player.direction,moving:false};ui();status(`Đã qua cửa: ${result.level.name}`);}
