el('delete-layer').addEventListener('click',()=>{if(level().objects.some(o=>o.layerId===activeLayer||o.coverLayerId===activeLayer)||level().regions.some(r=>r.layerId===activeLayer)||level().layers.length===1){status('Layer còn đối tượng/vùng tham chiếu. Chuyển chúng sang layer khác trước.');return;}edit(()=>{level().layers=level().layers.filter(l=>l.id!==activeLayer);activeLayer=level().layers[0].id;});});
