el('inspector').addEventListener('change',e=>{const n=e.target as HTMLInputElement|HTMLSelectElement|HTMLTextAreaElement,key=n.dataset.field;if(!key)return;edit(()=>{const o=object(),r=region(),l=level();if(key==='selectionX'||key==='selectionY'){if(!canEditSelection())return;const b=selectionBounds(project,l,selections);translateEntities(l,selections,key==='selectionX'?Number(n.value)-b.left:0,key==='selectionY'?Number(n.value)-b.top:0);}else if(o){if(key==='pivotX'||key==='pivotY'){o.pivot??={...project.assets.find(a=>a.id===o.assetId)!.pivot};o.pivot[key==='pivotX'?'x':'y']=Number(n.value);}else if(['x','y','scale','opacity'].includes(key))(o as any)[key]=Number(n.value);else if(['flipX','locked'].includes(key))(o as any)[key]=n.value==='true';else(o as any)[key]=n.value;}
  else if(r){if(key==='points')r.points=n.value.trim().split('\n').map(s=>{const[x,y]=s.split(',').map(Number);return {x,y};});else if(key==='enabled')r.enabled=n.value==='true';else if(key==='targetX'||key==='targetY'){if(n.value==='')r.target=null;else{const dest=project.levels.find(l=>l.id===r.targetLevelId);r.target??={...(dest?.spawn??{x:0,y:0})};r.target[key==='targetX'?'x':'y']=Number(n.value);}}else(r as any)[key]=n.value;}
  else {if(key==='levelName')l.name=n.value;else if(['width','height'].includes(key))(l as any)[key]=Number(n.value);else if(key==='spawnX'||key==='spawnY')l.spawn[key==='spawnX'?'x':'y']=Number(n.value);else if(key==='layerName')l.layers.find(l=>l.id===activeLayer)!.name=n.value;else if(key==='layerKind')l.layers.find(l=>l.id===activeLayer)!.kind=n.value as LayerKind;else(l as any)[key]=n.value;}});});
