el<HTMLSelectElement>('saved-projects').addEventListener('change',async()=>{const value=el<HTMLSelectElement>('saved-projects').value;if(!value)return;try{const raw=value.startsWith('draft:')?JSON.parse(localStorage.getItem(`game-solo-map-editor:${value.slice(6)}`)!):await(await fetch(`/api/map-editor/projects/${value}`)).json();await openProject(parseProject(raw));}catch(error){status(String(error));}});
