async function addAssets(assets:EditorAsset[]):Promise<void> {if(project.assets.length+assets.length>200)throw new Error('Thư viện tối đa 200 asset.');const next=structuredClone(project);next.assets.push(...assets);await loadAssets(next);edit(()=>{project.assets.push(...assets);chosenAsset=assets[0]?.id??chosenAsset;chosenPrefab='';if(assets[0]?.defaultLayer)activeLayer=level().layers.find(l=>l.kind===assets[0].defaultLayer)?.id??activeLayer;});setTool('place');ui();status(`Đã nhập ${assets.length} PNG. Chỉnh pivot và layer mặc định ở Thuộc tính asset.`);}
