  const lastId=localStorage.getItem('game-solo-map-editor-last');try{project=!libraryReset&&lastId?parseProject(JSON.parse(localStorage.getItem(`game-solo-map-editor:${lastId}`)!)):newProject(assets);}catch{project=newProject(assets);libraryReset=true;}
  if(project.assets.some(a=>a.parts.some(p=>p.file.startsWith('/assets/map-kit/')&&!libraryFiles.has(p.file)))){project=newProject(assets);libraryReset=true;}
  activeLayer=level().layers.find(l=>l.kind==='depth')?.id??level().layers[0].id;
  const catalog=await(await fetch('/assets/catalog.json',{cache:'no-store'})).json(),actor=catalog.actors.find((a:any)=>a.id==='AVATAR-NOVICE-MALE');atlas=normalizeAtlas(await(await fetch(actor.metadataUrl)).json());animation=new AnimationPlayer(atlas);actorImage=new Image();actorImage.src=actor.atlasUrl;
